package web

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"sort"
	"strings"
)

// The files the agent writes say so on their first line, and say that edits
// are replaced: the panel's state is the source of truth.
const banner = "Generated by LPanel. Changes made here are replaced the next time the account's sites change."

// renderInclude is /etc/httpd/conf.d/lpanel.conf, the one file the agent
// adds to Apache's own configuration. It defines the log format, a default
// site for names nobody serves, and includes every account's file.
//
// The sites folder is a variable, so a candidate can be tested whole without
// touching the live one: httpd -t -C "Define LPANEL_SITES <stage>".
//
// Alone, Apache answers on *:80 and *:443. Behind nginx (hybrid) it answers
// on 127.0.0.1's backend port only: nginx terminates HTTPS and says so in
// X-Forwarded-Proto, and the client's address comes from X-Forwarded-For.
func (m *Manager) renderInclude(sites string) []byte {
	hybrid := m.Server == "hybrid"
	var b strings.Builder
	b.WriteString("# " + banner + "\n\n")
	// %O and %I are bytes sent and received (mod_logio), for bandwidth.
	b.WriteString(`LogFormat "%v %h %l %u %t \"%r\" %>s %O %I \"%{Referer}i\" \"%{User-Agent}i\"" lpanel` + "\n\n")
	if hybrid {
		b.WriteString("# Behind nginx: the visitor's address, not nginx's, and whether they\n")
		b.WriteString("# came over HTTPS (nginx always sets the header, so no visitor can).\n")
		b.WriteString("<IfModule remoteip_module>\n    RemoteIPHeader X-Forwarded-For\n    RemoteIPInternalProxy 127.0.0.1\n</IfModule>\n")
		b.WriteString("SetEnvIf X-Forwarded-Proto \"^https$\" HTTPS=on\n\n")
	} else {
		b.WriteString("# Certificate checks (HTTP-01): every site answers them from here.\n")
		fmt.Fprintf(&b, "<Directory \"%s\">\n    Options None\n    AllowOverride None\n    Require all granted\n    ForceType text/plain\n</Directory>\n\n", m.Challenges)
	}
	b.WriteString("<IfDefine !LPANEL_SITES>\n    Define LPANEL_SITES " + sites + "\n</IfDefine>\n\n")
	b.WriteString("# The first site answers names that no account serves: a 404,\n")
	b.WriteString("# never some customer's site.\n")
	b.WriteString("<VirtualHost " + m.apacheListen() + ">\n")
	b.WriteString("    ServerName lpanel-default.invalid\n")
	b.WriteString("    RewriteEngine On\n")
	if !hybrid {
		// The server's own hostname is checked here too.
		b.WriteString(m.challengeRule())
	}
	b.WriteString("    RewriteRule ^ - [R=404,L]\n")
	b.WriteString("</VirtualHost>\n\n")
	// The same on every stack: mod_ssl is loaded either way, and a graceful
	// reload that changes the session cache leaves Apache dead
	// ("shared memory segment too small").
	b.WriteString("<IfModule ssl_module>\n    SSLSessionCache shmcb:/run/httpd/lpanel-sslcache(512000)\n    SSLSessionCacheTimeout 300\n</IfModule>\n\n")
	if !hybrid {
		b.WriteString("# HTTPS. The first site on 443 presents the server's own certificate\n")
		b.WriteString("# for names no account serves.\n")
		b.WriteString("Listen 443 https\n")
		b.WriteString("SSLProtocol all -SSLv3 -TLSv1 -TLSv1.1\n")
		b.WriteString("SSLHonorCipherOrder off\n")
		b.WriteString("<VirtualHost *:443>\n")
		b.WriteString("    ServerName lpanel-default.invalid\n")
		b.WriteString("    SSLEngine on\n")
		fmt.Fprintf(&b, "    SSLCertificateFile \"%s\"\n    SSLCertificateKeyFile \"%s\"\n", m.HostCert, m.HostKey)
		b.WriteString("    RewriteEngine On\n")
		b.WriteString("    RewriteRule ^ - [R=404,L]\n")
		b.WriteString("</VirtualHost>\n\n")
	}
	b.WriteString("IncludeOptional ${LPANEL_SITES}/*.conf\n")
	return []byte(b.String())
}

// challengeRule serves /.well-known/acme-challenge/<token> from the
// challenge folder before anything else in the site: before its redirects,
// the www. choice, a suspension or a move to HTTPS.
func (m *Manager) challengeRule() string {
	return fmt.Sprintf("    RewriteRule ^/\\.well-known/acme-challenge/([A-Za-z0-9_-]+)$ %s/$1 [END]\n", m.Challenges)
}

// siteFiles renders the account's file for each server of the stack, and
// one revision for them all: a hash of every file's content. Each site sends
// the revision in a header (nginx in front sends X-LPanel-Front), which is
// how the probe knows each server serves this version and not the one
// before. A file of the other stack, left from before a switch, goes.
func (m *Manager) siteFiles(a ApplyArgs, home string) ([]file, string) {
	var apache, nginx string
	if m.usesApache() {
		apache = m.renderApacheSites(a, home)
	}
	if m.usesNginx() {
		nginx = m.renderNginxSites(a, home)
	}
	sum := sha256.Sum256([]byte(apache + "\x00" + nginx))
	rev := hex.EncodeToString(sum[:])[:16]
	head := fmt.Sprintf("# %s\n# Account %s, revision %s.\n\n", banner, a.Username, rev)
	var files []file
	for _, f := range []struct {
		server, path, body string
		used               bool
	}{{"httpd", m.siteFile(a.Username), apache, m.usesApache()}, {"nginx", m.nginxFile(a.Username), nginx, m.usesNginx()}} {
		if f.used {
			files = append(files, file{path: f.path, server: f.server, content: []byte(head + strings.ReplaceAll(f.body, "@REVISION@", rev))})
		} else {
			files = append(files, file{path: f.path, server: f.server})
		}
	}
	return files, rev
}

// renderApacheSites is one account's Apache file: a VirtualHost per site,
// and one more on 443 for each site with a certificate (Apache alone; behind
// nginx, nginx serves HTTPS), with @REVISION@ where the revision goes.
func (m *Manager) renderApacheSites(a ApplyArgs, home string) string {
	var b strings.Builder
	for i, s := range a.Sites {
		if i > 0 {
			b.WriteString("\n")
		}
		t, secure := a.tls[s.Name]
		secure = secure && m.Server == "apache"
		// Plain HTTP only sends visitors on, when the owner asks.
		m.apacheSite(&b, a, s, home, nil, secure && s.TLS.Force)
		if secure {
			b.WriteString("\n")
			m.apacheSite(&b, a, s, home, &t, false)
		}
	}
	return b.String()
}

// apacheSite writes one VirtualHost of a site: on port 80 (or the backend
// port) when t is nil, else on 443 with t's certificate. toHTTPS makes it
// a redirect to HTTPS and nothing else.
func (m *Manager) apacheSite(b *strings.Builder, a ApplyArgs, s Site, home string, t *tlsFiles, toHTTPS bool) {
	listen := m.apacheListen()
	if t != nil {
		listen = "*:443"
	}
	fmt.Fprintf(b, "<VirtualHost %s>\n", listen)
	fmt.Fprintf(b, "    ServerName %s\n", s.Name)
	if len(s.Aliases) > 0 {
		fmt.Fprintf(b, "    ServerAlias %s\n", strings.Join(s.Aliases, " "))
	}
	b.WriteString("    Header always set X-LPanel-Revision \"@REVISION@\"\n")
	// Behind nginx, nginx's log has every request already.
	if m.Server != "hybrid" {
		fmt.Fprintf(b, "    CustomLog \"%s/%s.access.log\" lpanel\n", m.LogDir, a.Username)
	}
	fmt.Fprintf(b, "    ErrorLog \"%s/%s.error.log\"\n", m.LogDir, a.Username)
	if t != nil {
		b.WriteString("    SSLEngine on\n")
		fmt.Fprintf(b, "    SSLCertificateFile \"%s\"\n    SSLCertificateKeyFile \"%s\"\n", t.crt, t.key)
	} else if m.Server != "hybrid" {
		// Behind nginx, nginx answers the checks.
		b.WriteString("    RewriteEngine On\n")
		b.WriteString(m.challengeRule())
	}
	if toHTTPS {
		b.WriteString("    RewriteRule ^ https://%{HTTP_HOST}%{REQUEST_URI} [R=301,L]\n")
		b.WriteString("</VirtualHost>\n")
		return
	}
	if a.Suspended || a.Limited {
		why := "This site is suspended."
		if !a.Suspended {
			why = "This site has used its bandwidth for this month."
		}
		b.WriteString("    RewriteEngine On\n")
		b.WriteString("    RewriteRule ^ - [R=503,L]\n")
		fmt.Fprintf(b, "    ErrorDocument 503 \"%s\"\n", why)
		b.WriteString("</VirtualHost>\n")
		return
	}
	root := home + "/" + s.Docroot
	fmt.Fprintf(b, "    DocumentRoot \"%s\"\n", root)
	renderFeatures(b, s)
	fmt.Fprintf(b, "    <Directory \"%s\">\n", root)
	b.WriteString("        Options -Indexes +SymLinksIfOwnerMatch\n")
	// .htaccess works, but cannot turn on following any link or
	// running CGI: only what is listed.
	b.WriteString("        AllowOverride AuthConfig FileInfo Indexes Limit Options=Indexes,MultiViews,SymLinksIfOwnerMatch\n")
	b.WriteString("        Require all granted\n")
	b.WriteString("        DirectoryIndex index.php index.html index.htm\n")
	b.WriteString("    </Directory>\n")
	m.renderProtected(b, a, s, root)
	b.WriteString("    <FilesMatch \"\\.php$\">\n")
	fmt.Fprintf(b, "        SetHandler \"proxy:unix:%s|fcgi://lpanel-%s-%s\"\n", m.socket(s.PHP, a.Username), a.Username, s.PHP)
	b.WriteString("    </FilesMatch>\n")
	b.WriteString("</VirtualHost>\n")
}

// renderPool is the account's PHP-FPM pool for one PHP version. It runs as
// the account's own user; only the web server (its group) may use its socket.
func (m *Manager) renderPool(a ApplyArgs, home, version string) []byte {
	var b strings.Builder
	fmt.Fprintf(&b, "; %s\n; Account %s, PHP %s.%s.\n\n", banner, a.Username, version[:1], version[1:])
	fmt.Fprintf(&b, "[lpanel-%s]\n", a.Username)
	fmt.Fprintf(&b, "user = %s\ngroup = %s\n", a.Username, a.Username)
	fmt.Fprintf(&b, "listen = %s\n", m.socket(version, a.Username))
	fmt.Fprintf(&b, "listen.owner = %s\nlisten.group = %s\nlisten.mode = 0660\n", a.Username, m.WebGroup)
	b.WriteString("pm = ondemand\n")
	fmt.Fprintf(&b, "pm.max_children = %d\n", a.Pool.MaxChildren)
	b.WriteString("pm.process_idle_timeout = 30s\npm.max_requests = 500\n")
	fmt.Fprintf(&b, "chdir = %s\n", home)
	b.WriteString("security.limit_extensions = .php\n")
	// Sessions, uploads and temporary files stay in the account's own
	// folder: Remi's shared session folder is not writable by the account,
	// and a shared one would let accounts read each other's sessions.
	for _, k := range []string{"session.save_path", "upload_tmp_dir", "sys_temp_dir"} {
		fmt.Fprintf(&b, "php_admin_value[%s] = %s/tmp\n", k, home)
	}
	fmt.Fprintf(&b, "php_admin_value[error_log] = %s/logs/php-error.log\n", home)
	b.WriteString("php_admin_flag[log_errors] = on\n")
	if settings := a.PHPSettings[version]; len(settings) > 0 {
		b.WriteString("\n; The owner's php.ini settings for this version.\n")
		renderPHPSettings(&b, settings)
	}
	return []byte(b.String())
}

// versions are the PHP versions an account's sites use, sorted.
func versions(a ApplyArgs) []string {
	seen := map[string]bool{}
	var out []string
	for _, s := range a.Sites {
		if !seen[s.PHP] {
			seen[s.PHP] = true
			out = append(out, s.PHP)
		}
	}
	sort.Strings(out)
	return out
}
